    "gambar": "<div style=\"display:flex;align-items:center;gap:10px;flex-wrap:wrap;\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 80 80\" width=\"76\" height=\"76\" style=\"display:inline-block;vertical-align:middle;background:#fff;border:1.5px solid #cbd5e1;border-radius:8px;\"><g transform=\"translate(40,40) rotate(90) translate(-40,-40)\"><polygon points=\"40,14 54,34 45,34 45,62 35,62 35,34 26,34\" fill=\"#7c3aed\" stroke=\"#7c3aed\" stroke-width=\"2.2\"/></g></svg><span style=\"font-weight:800;color:#475569;\">→</span><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 80 80\" width=\"76\" height=\"76\" style=\"display:inline-block;vertical-align:middle;background:#fff;border:1.5px solid #cbd5e1;border-radius:8px;\"><g transform=\"translate(40,40) rotate(225) translate(-40,-40)\"><polygon points=\"40,14 54,34 45,34 45,62 35,62 35,34 26,34\" fill=\"#ffffff\" stroke=\"#7c3aed\" stroke-width=\"2.2\"/></g></svg><span style=\"font-weight:800;color:#475569;\">→</span><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 80 80\" width=\"76\" height=\"76\" style=\"display:inline-block;vertical-align:middle;background:#fff;border:1.5px solid #cbd5e1;border-radius:8px;\"><g transform=\"translate(40,40) rotate(0) translate(-40,-40)\"><polygon points=\"40,14 54,34 45,34 45,62 35,62 35,34 26,34\" fill=\"#7c3aed\" stroke=\"#7c3aed\" stroke-width=\"2.2\"/></g></svg><span style=\"font-weight:800;color:#475569;\">→</span><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 80 80\" width=\"76\" height=\"76\" style=\"display:inline-block;vertical-align:middle;background:#fff;border:1.5px solid #cbd5e1;border-radius:8px;\"><text x=\"40\" y=\"47\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#1e3a8a\">?</text></svg></div>"
