        "teks": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 80 80\" width=\"76\" height=\"76\" style=\"display:inline-block;vertical-align:middle;background:#fff;border:1.5px solid #cbd5e1;border-radius:8px;\"><line x1=\"40\" y1=\"8\" x2=\"40\" y2=\"72\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/><line x1=\"8\" y1=\"40\" x2=\"72\" y2=\"40\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/><line x1=\"10\" y1=\"70\" x2=\"70\" y2=\"10\" stroke=\"#1e3a8a\" stroke-width=\"2.5\"/><rect x=\"15\" y=\"51\" width=\"14\" height=\"14\" fill=\"#0f172a\"/></svg>",
        "benar": false,
